on conflict (id) do update set name = excluded.name, series = excluded.series, printed_total = excluded.printed_total, total = excluded.total, release_date = excluded.release_date, logo_url = excluded.logo_url, symbol_url = excluded.symbol_url;

on conflict (id) do update set set_id = excluded.set_id, number = excluded.number, name = excluded.name, supertype = excluded.supertype, subtype = excluded.subtype, type = excluded.type, rarity = excluded.rarity, rarity_raw = excluded.rarity_raw, image_small = excluded.image_small, image_large = excluded.image_large, market_price_usd = excluded.market_price_usd, price_updated_at = excluded.price_updated_at;
